use std :: path :: Path ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Walks through `input` token-by-token and wraps absolute file paths."] # [doc = ""] # [doc = " Handles both unquoted tokens (split on whitespace) and quoted strings"] # [doc = " (single or double quotes) so that paths containing spaces are kept"] # [doc = " together as a single token."] fn wrap_tokens (input : & str) -> String { let mut result = String :: with_capacity (input . len () + 32) ; let mut remaining = input ; while ! remaining . is_empty () { let ws_end = remaining . find (| c : char | ! c . is_whitespace ()) . unwrap_or (remaining . len ()) ; result . push_str (remaining . get (.. ws_end) . unwrap_or ("")) ; remaining = remaining . get (ws_end ..) . unwrap_or ("") ; if remaining . is_empty () { break ; } if remaining . starts_with ("@[") && let Some (close) = remaining . find (']') { result . push_str (remaining . get (..= close) . unwrap_or ("")) ; remaining = remaining . get (close . saturating_add (1) ..) . unwrap_or ("") ; continue ; } let first_char = remaining . as_bytes () . first () . copied () . unwrap_or (0) ; if first_char == b'\'' || first_char == b'"' { let quote = first_char as char ; if let Some (close) = remaining . get (1 ..) . and_then (| s | s . find (quote)) { let token_end = close . saturating_add (2) ; let token = remaining . get (.. token_end) . unwrap_or ("") ; let clean = strip_surrounding_quotes (token) ; if let Some (resolved) = resolve_file_path (clean) { result . push_str (& format ! ("@[{}]" , resolved)) ; } else { result . push_str (token) ; } remaining = remaining . get (token_end ..) . unwrap_or ("") ; continue ; } } let token_end = find_token_end (remaining) ; let token = remaining . get (.. token_end) . unwrap_or ("") ; if let Some (resolved) = resolve_file_path (token) { result . push_str (& format ! ("@[{}]" , resolved)) ; } else { result . push_str (token) ; } remaining = remaining . get (token_end ..) . unwrap_or ("") ; } result }